// Conversion offer logic: triggers a special offer popup when user shows purchase intent
// This module is called by the pricing page after a visitor views pricing for >5 seconds
// or hovers over the checkout button.

const offers = {
  default: {
    discount: 0.15,
    message: 'Get 15% off if you buy now!',
    expiresInMinutes: 10
  },
  premium: {
    discount: 0.25,
    message: 'Exclusive 25% discount for premium visitors!',
    expiresInMinutes: 5
  }
};

function getOfferForVisitor(visitorProfile) {
  // Simple logic: return premium offer for returning visitors
  if (visitorProfile && visitorProfile.visitCount > 1) {
    return offers.premium;
  }
  return offers.default;
}

function createConversionOffer(visitorProfile) {
  const offer = getOfferForVisitor(visitorProfile);
  return {
    ...offer,
    expiresAt: Date.now() + offer.expiresInMinutes * 60 * 1000,
    code: 'CONVERT' + Math.random().toString(36).substring(2, 8).toUpperCase()
  };
}

module.exports = { createConversionOffer, offers };
